import { FilterForm } from 'models';
import {
  BarClickParams,
  ViewByDisabledCondition,
  WaterfallConfig,
} from 'pages/pillars/ValueCreation/PerformanceTool/config/types';

import { hasSpecificValue } from '../utils/resolveCommercialResultsWaterfallOptions';

const BASE_WATERFALL_FILTER_DISABLED_CONDITIONS: ViewByDisabledCondition[] = [
  ({ activeSubFilters }) => activeSubFilters?.waterfall_filter === 'sku',
];

const handleBrandView = ({
  clickedLabel,
  updateForm,
  apply,
}: Pick<BarClickParams, 'updateForm' | 'apply'> & {
  clickedLabel: string | string[];
}) => {
  const brandLabel = Array.isArray(clickedLabel)
    ? clickedLabel[0]
    : clickedLabel;

  updateForm('brands', brandLabel);
  apply();
};

const handleSubBrandView = ({
  clickedLabel,
  updateForm,
  apply,
}: Pick<BarClickParams, 'updateForm' | 'apply'> & {
  clickedLabel: string;
}) => {
  updateForm('sub_brands', clickedLabel);
  apply();
};

const handleRegionView = ({
  clickedLabel,
  updateForm,
  apply,
}: Pick<BarClickParams, 'updateForm' | 'apply'> & {
  clickedLabel: string;
}) => {
  updateForm('region', clickedLabel);
  apply();
};

const handleChannelView = ({
  clickedLabel,
  updateForm,
  apply,
}: Pick<BarClickParams, 'updateForm' | 'apply'> & {
  clickedLabel: string;
}) => {
  updateForm('channel', clickedLabel);
  apply();
};

const handlePackTypeView = ({
  clickedLabel,
  updateForm,
  apply,
}: Pick<BarClickParams, 'updateForm' | 'apply'> & {
  clickedLabel: string;
}) => {
  updateForm('pack_type', clickedLabel);
  apply();
};

const handleSkuView = ({
  clickedLabel,
  updateForm,
  apply,
  applied,
}: Pick<BarClickParams, 'updateForm' | 'apply' | 'applied'> & {
  clickedLabel: string;
}) => {
  if (hasSpecificValue(applied.sku)) {
    updateForm('sku', 'All');
  } else {
    updateForm('sku', clickedLabel);
  }
  apply();
};

export const createBaseWaterfallConfig = (
  kpiName: string,
): WaterfallConfig => ({
  kpiName,

  viewByToGrouping: {},

  groupingToViewBy: {},

  isViewByDisabled: (contextKey, activeSubFilters, applied) =>
    BASE_WATERFALL_FILTER_DISABLED_CONDITIONS.some((condition) =>
      condition({ contextKey, activeSubFilters, applied }),
    ),

  getDisabledIndexes: (labels = []) => {
    const indices = new Set<number>([0, labels.length - 1]);

    labels.forEach((label, index) => {
      const parsedLabel = Array.isArray(label) ? label[0] : label;

      if (['N/A', 'NAB + Others', 'Others'].includes(parsedLabel)) {
        indices.add(index);
      }
    });

    return Array.from(indices);
  },

  handleBarClick: ({
    index,
    labels,
    activeSubFilters,
    applied,
    updateForm,
    apply,
    syncWaterfallFilterAfterDrill,
  }: BarClickParams) => {
    const currentView = activeSubFilters?.waterfall_filter as string;

    const clickedLabel = labels?.[index];
    if (
      !clickedLabel &&
      (currentView !== 'sku' || !hasSpecificValue(applied.sku))
    )
      return;

    const handlers: Record<string, VoidFunction> = {
      region: () =>
        handleRegionView({
          clickedLabel,
          updateForm,
          apply,
        }),
      brand: () =>
        handleBrandView({
          clickedLabel,
          updateForm,
          apply,
        }),
      channel: () => handleChannelView({ clickedLabel, updateForm, apply }),
      pack_type: () => handlePackTypeView({ clickedLabel, updateForm, apply }),
      sub_brand: () => handleSubBrandView({ clickedLabel, updateForm, apply }),
      sku: () => handleSkuView({ clickedLabel, updateForm, apply, applied }),
    };

    handlers[currentView]?.();
    syncWaterfallFilterAfterDrill?.(currentView, clickedLabel);
  },

  getContextKey: (applied: FilterForm) => {
    if (!applied) {
      return 'global';
    }

    if (hasSpecificValue(applied.sub_brands)) {
      return 'sub_brand';
    }

    if (hasSpecificValue(applied.brands)) {
      return 'brand';
    }

    return 'global';
  },
});
